/*
 * Thin wrapper around child_process.spawn for invoking the `intropy` CLI.
 *
 * Modeled on @backstage/plugin-scaffolder-node's executeShellCommand, which we
 * can't use directly because it discards both the exit code and stderr — we
 * need the exit code (2 = usage/1 = runtime) to produce useful errors, and a
 * tail of stderr to surface in them.
 */

import { spawn } from 'node:child_process';
import { LoggerService } from '@backstage/backend-plugin-api';

const STDERR_TAIL_LINES = 50;

export interface RunIntropyCliOptions {
  /** Path to the intropy binary, or just `intropy` to resolve from PATH. */
  command: string;
  args: string[];
  cwd: string;
  env: NodeJS.ProcessEnv;
  logger: LoggerService;
}

export interface RunIntropyCliResult {
  exitCode: number;
  /** Last STDERR_TAIL_LINES lines emitted on stderr, for error messages. */
  stderrTail: string[];
}

/**
 * Spawns the intropy CLI with args passed as an array (no shell, so values
 * containing spaces or shell metacharacters are never interpreted). stdin is
 * ignored, which guarantees a non-TTY so the CLI's interactive prompts stay
 * disabled even independently of the --no-input flag.
 *
 * Resolves for any exit code (the caller maps codes to errors); rejects only
 * when the process cannot be spawned at all.
 */
export async function runIntropyCli(
  options: RunIntropyCliOptions,
): Promise<RunIntropyCliResult> {
  const { command, args, cwd, env, logger } = options;

  return new Promise<RunIntropyCliResult>((resolve, reject) => {
    const child = spawn(command, args, {
      cwd,
      env,
      stdio: ['ignore', 'pipe', 'pipe'],
    });

    const stderrTail: string[] = [];
    const pushTail = (line: string) => {
      stderrTail.push(line);
      if (stderrTail.length > STDERR_TAIL_LINES) {
        stderrTail.shift();
      }
    };

    // Line-buffer each stream so partial chunks don't produce split log lines.
    const lineStreamer = (onLine: (line: string) => void) => {
      let buffer = '';
      return (chunk: Buffer) => {
        buffer += chunk.toString('utf8');
        const lines = buffer.split('\n');
        buffer = lines.pop() ?? '';
        for (const line of lines) {
          onLine(line);
        }
      };
    };

    child.stdout.on(
      'data',
      lineStreamer(line => logger.info(line)),
    );
    child.stderr.on(
      'data',
      lineStreamer(line => {
        logger.error(line);
        pushTail(line);
      }),
    );

    child.on('error', err => {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') {
        reject(
          new Error(
            `intropy CLI not found at '${command}'. Install it on PATH or set intropy.cli.path in app-config.`,
          ),
        );
        return;
      }
      reject(err);
    });

    child.on('close', code => {
      resolve({ exitCode: code ?? 1, stderrTail });
    });
  });
}

import { createTemplateAction } from '@backstage/plugin-scaffolder-node';
import {
  resolveSafeChildPath,
  RootConfigService,
} from '@backstage/backend-plugin-api';
import { InputError } from '@backstage/errors';
import fs from 'fs-extra';
import path from 'node:path';
import { runIntropyCli } from './runIntropyCli';

export const intropyIntCreateExamples = [
  {
    description: 'Scaffold an integration from a blueprint',
    example: `
steps:
  - id: create
    action: intropy:int:create
    input:
      blueprint: hello-world
      name: MyApi
      targetPath: ./output/integrations/my-api
      values:
        someBlueprintParam: value
`,
  },
];

/** Shape of the CLI's --output-json CreateResult. Parsed defensively. */
interface CreateResult {
  blueprint?: string;
  version?: string;
  outputDir?: string;
}

/**
 * Creates the intropy:int:create action.
 *
 * Runs `intropy int create <blueprint>` inside the scaffolder workspace to
 * generate an integration. The CLI is the single source of scaffolding logic;
 * this action just adapts it to the Backstage scaffolder (workspace-relative
 * paths, structured errors, and registered outputs).
 */
export function createIntropyIntCreateAction(options: {
  config: RootConfigService;
}) {
  const { config } = options;

  return createTemplateAction({
    id: 'intropy:int:create',
    description:
      'Scaffolds an integration by running the intropy CLI (int create) against a blueprint.',
    examples: intropyIntCreateExamples,
    schema: {
      input: {
        blueprint: z => z.string().describe('Blueprint id, e.g. hello-world'),
        name: z =>
          z.string().describe('Name of the integration to create'),
        targetPath: z =>
          z
            .string()
            .optional()
            .describe(
              'Workspace-relative directory to generate into. Defaults to the workspace root.',
            ),
        values: z =>
          z
            .record(z.any())
            .optional()
            .describe('Blueprint parameter values (may be nested).'),
      },
      output: {
        outputDir: z =>
          z
            .string()
            .describe('Workspace-relative path of the generated integration.'),
        blueprintVersion: z =>
          z.string().describe('Resolved blueprint version.'),
        blueprint: z => z.string().describe('Resolved blueprint id.'),
      },
    },
    async handler(ctx) {
      const { blueprint, name, targetPath, values } = ctx.input;

      const outDir = resolveSafeChildPath(
        ctx.workspacePath,
        targetPath ?? '.',
      );
      await fs.ensureDir(outDir);

      // Values and the result file go in an auto-cleaned temp dir so they never
      // land in the published workspace.
      const tmpDir = await ctx.createTemporaryDirectory();
      const resultPath = path.join(tmpDir, 'result.json');

      const args = [
        'int',
        'create',
        blueprint,
        '--output',
        outDir,
        '--name',
        name,
        '--no-input',
        '--skip-install-skills',
        '--output-json',
        resultPath,
      ];

      // JSON is a strict subset of YAML, so the CLI's -f parser accepts it and
      // we avoid --set string-flattening of nested values.
      if (values && Object.keys(values).length > 0) {
        const valuesPath = path.join(tmpDir, 'values.json');
        await fs.writeFile(valuesPath, JSON.stringify(values, null, 2), 'utf8');
        args.push('-f', valuesPath);
      }

      const cliPath =
        config.getOptionalString('intropy.cli.path') ?? 'intropy';

      ctx.logger.info(
        `Running intropy int create ${blueprint} (name: ${name})`,
      );

      const { exitCode, stderrTail } = await runIntropyCli({
        command: cliPath,
        args,
        cwd: ctx.workspacePath,
        env: { ...process.env },
        logger: ctx.logger,
      });

      if (exitCode === 2) {
        throw new InputError(
          `intropy rejected the input for blueprint '${blueprint}' (usage error). ` +
            `Check that all required blueprint parameters are provided.\n${stderrTail.join(
              '\n',
            )}`,
        );
      }
      if (exitCode !== 0) {
        throw new Error(
          `intropy int create failed (exit ${exitCode}).\n${stderrTail.join(
            '\n',
          )}`,
        );
      }

      let result: CreateResult = {};
      try {
        result = JSON.parse(await fs.readFile(resultPath, 'utf8'));
      } catch (err) {
        ctx.logger.warn(
          `intropy succeeded but its --output-json result could not be read: ${err}`,
        );
      }

      // The CLI reports an absolute outputDir; downstream steps (fs, publish)
      // need it relative to the workspace. Fall back to the requested outDir.
      const absOutputDir = result.outputDir ?? outDir;
      const relOutputDir = path.relative(ctx.workspacePath, absOutputDir);
      if (relOutputDir.startsWith('..') || path.isAbsolute(relOutputDir)) {
        throw new Error(
          `intropy wrote outside the workspace (${absOutputDir}); refusing to continue.`,
        );
      }

      ctx.output('outputDir', relOutputDir);
      ctx.output('blueprintVersion', result.version ?? 'unknown');
      ctx.output('blueprint', result.blueprint ?? blueprint);

      ctx.logger.info(
        `Created ${result.blueprint ?? blueprint}@${
          result.version ?? 'unknown'
        } at ${relOutputDir}`,
      );
    },
  });
}

