/**
 * Scaffolder backend module that adds the `intropy:int:create` action,
 * scaffolding integrations by running the intropy CLI.
 *
 * @packageDocumentation
 */

export { scaffolderModuleIntropy as default } from './module';
export {
  createIntropyIntCreateAction,
  intropyIntCreateExamples,
} from './intropyIntCreate';
export { runIntropyCli } from './runIntropyCli';
export type {
  RunIntropyCliOptions,
  RunIntropyCliResult,
} from './runIntropyCli';

import fs from 'fs-extra';
import os from 'os';
import path from 'path';
import { createIntropyIntCreateAction } from './intropyIntCreate';
import { runIntropyCli, RunIntropyCliResult } from './runIntropyCli';

jest.mock('./runIntropyCli');
const mockRun = runIntropyCli as jest.MockedFunction<typeof runIntropyCli>;

function makeConfig(data: Record<string, any> = {}) {
  return {
    getOptionalString: (key: string) => {
      const value = key
        .split('.')
        .reduce<any>((cur, part) => cur?.[part], data);
      return typeof value === 'string' ? value : undefined;
    },
  } as any;
}

describe('intropy:int:create', () => {
  let workspacePath: string;
  let tmpDir: string;
  let outputs: Record<string, unknown>;

  const makeCtx = (input: Record<string, unknown>) => {
    outputs = {};
    return {
      input,
      workspacePath,
      logger: {
        info: jest.fn(),
        warn: jest.fn(),
        error: jest.fn(),
        debug: jest.fn(),
      },
      createTemporaryDirectory: jest.fn(async () => tmpDir),
      output: (key: string, value: unknown) => {
        outputs[key] = value;
      },
    } as any;
  };

  // Default: the CLI succeeds and writes a CreateResult to the --output-json path.
  const succeedWith = (result: Record<string, unknown>) => {
    mockRun.mockImplementation(async ({ args }): Promise<RunIntropyCliResult> => {
      const idx = args.indexOf('--output-json');
      await fs.writeFile(args[idx + 1], JSON.stringify(result), 'utf8');
      return { exitCode: 0, stderrTail: [] };
    });
  };

  beforeEach(async () => {
    workspacePath = await fs.mkdtemp(path.join(os.tmpdir(), 'intropy-ws-'));
    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'intropy-tmp-'));
    mockRun.mockReset();
  });

  afterEach(async () => {
    await fs.remove(workspacePath);
    await fs.remove(tmpDir);
  });

  it('invokes the CLI with the expected argv and registers outputs', async () => {
    succeedWith({
      blueprint: 'dapr-minimal-api',
      version: 'v0.1.5',
      outputDir: path.join(workspacePath, 'output/my-api'),
    });

    const action = createIntropyIntCreateAction({ config: makeConfig() });
    await action.handler(
      makeCtx({
        blueprint: 'hello-world',
        name: 'MyApi',
        targetPath: './output/my-api',
      }),
    );

    const { command, args } = mockRun.mock.calls[0][0];
    expect(command).toBe('intropy');
    // Fixed prefix, in order.
    expect(args.slice(0, 3)).toEqual(['int', 'create', 'hello-world']);
    expect(args).toContain('--no-input');
    expect(args).toContain('--skip-install-skills');
    expect(args[args.indexOf('--name') + 1]).toBe('MyApi');
    expect(args[args.indexOf('--output') + 1]).toBe(
      path.join(workspacePath, 'output/my-api'),
    );
    // No values → no -f flag.
    expect(args).not.toContain('-f');

    expect(outputs).toEqual({
      outputDir: path.normalize('output/my-api'),
      blueprintVersion: 'v0.1.5',
      blueprint: 'dapr-minimal-api',
    });
  });

  it('writes nested values to a JSON file and passes it with -f', async () => {
    succeedWith({ outputDir: workspacePath, version: 'v1' });

    const action = createIntropyIntCreateAction({ config: makeConfig() });
    await action.handler(
      makeCtx({
        blueprint: 'hello-world',
        name: 'MyApi',
        values: { nested: { a: 1 }, list: ['x', 'y'] },
      }),
    );

    const { args } = mockRun.mock.calls[0][0];
    const valuesFile = args[args.indexOf('-f') + 1];
    expect(JSON.parse(await fs.readFile(valuesFile, 'utf8'))).toEqual({
      nested: { a: 1 },
      list: ['x', 'y'],
    });
  });

  it('resolves the binary path from config when set', async () => {
    succeedWith({ outputDir: workspacePath, version: 'v1' });

    const action = createIntropyIntCreateAction({
      config: makeConfig({ intropy: { cli: { path: '/opt/intropy' } } }),
    });
    await action.handler(makeCtx({ blueprint: 'hello-world', name: 'MyApi' }));

    expect(mockRun.mock.calls[0][0].command).toBe('/opt/intropy');
  });

  it('throws InputError on exit code 2', async () => {
    mockRun.mockResolvedValue({
      exitCode: 2,
      stderrTail: ['error: missing required parameter(s): name'],
    });

    const action = createIntropyIntCreateAction({ config: makeConfig() });
    await expect(
      action.handler(makeCtx({ blueprint: 'hello-world', name: 'MyApi' })),
    ).rejects.toThrow(/missing required parameter/);
  });

  it('throws a runtime error on other non-zero exit codes', async () => {
    mockRun.mockResolvedValue({
      exitCode: 1,
      stderrTail: ['error: could not download blueprint'],
    });

    const action = createIntropyIntCreateAction({ config: makeConfig() });
    await expect(
      action.handler(makeCtx({ blueprint: 'hello-world', name: 'MyApi' })),
    ).rejects.toThrow(/exit 1/);
  });

  it('rejects a targetPath that escapes the workspace', async () => {
    const action = createIntropyIntCreateAction({ config: makeConfig() });
    await expect(
      action.handler(
        makeCtx({
          blueprint: 'hello-world',
          name: 'MyApi',
          targetPath: '../../etc',
        }),
      ),
    ).rejects.toThrow();
    expect(mockRun).not.toHaveBeenCalled();
  });
});

import fs from 'fs-extra';
import os from 'os';
import path from 'path';
import { runIntropyCli } from './runIntropyCli';

// Exercises the real spawn path with a throwaway shell script, so no CLI or
// mocking is involved.
describe('runIntropyCli', () => {
  let dir: string;
  const logger = {
    info: jest.fn(),
    warn: jest.fn(),
    error: jest.fn(),
    debug: jest.fn(),
  } as any;

  const writeFakeCli = async (script: string) => {
    const file = path.join(dir, 'fake-cli.sh');
    await fs.writeFile(file, `#!/bin/sh\n${script}\n`, { mode: 0o755 });
    return file;
  };

  beforeEach(async () => {
    dir = await fs.mkdtemp(path.join(os.tmpdir(), 'run-intropy-'));
    jest.clearAllMocks();
  });

  afterEach(async () => {
    await fs.remove(dir);
  });

  it('streams stdout/stderr to the logger and returns the exit code', async () => {
    const cli = await writeFakeCli(
      'echo "hello stdout"; echo "oops" 1>&2; exit 0',
    );

    const result = await runIntropyCli({
      command: cli,
      args: [],
      cwd: dir,
      env: process.env,
      logger,
    });

    expect(result.exitCode).toBe(0);
    expect(logger.info).toHaveBeenCalledWith('hello stdout');
    expect(logger.error).toHaveBeenCalledWith('oops');
  });

  it('captures a tail of stderr and preserves a non-zero exit code', async () => {
    const cli = await writeFakeCli('echo "line one" 1>&2; exit 2');

    const result = await runIntropyCli({
      command: cli,
      args: [],
      cwd: dir,
      env: process.env,
      logger,
    });

    expect(result.exitCode).toBe(2);
    expect(result.stderrTail).toContain('line one');
  });

  it('rejects with a helpful message when the binary is missing', async () => {
    await expect(
      runIntropyCli({
        command: path.join(dir, 'does-not-exist'),
        args: [],
        cwd: dir,
        env: process.env,
        logger,
      }),
    ).rejects.toThrow(/intropy CLI not found/);
  });
});

